cat > "$P/integration/codemode/codemode_host.mjs" <<'JS'
/**
 * Optional Pi Code Mode sidecar. Scripts execute in upstream QuickJS, not Node.
 * Only mission-scoped read tools are injected. Host-side Dottie API rechecks
 * actor, mission, scope and call budget on *every* nested tool invocation.
 *
 * NOT a deployed agent. Requires separately reviewed/pinned npm dependency,
 * separately authorized endpoint and an active, operator-created mission.
 */
import { readFile, lstat } from 'node:fs/promises';
import { CodemodeSandbox } from '@earendil-works/pi-codemode';

const LIMIT = 64 * 1024;
const TIMEOUT_MS = 15_000;

function requiredEnv(name) {
  const value = process.env[name];
  if (typeof value !== 'string' || !value) throw new Error(`Required ${name} was not provisioned`);
  return value;
}

function authorizeEndpoint(raw) {
  const u = new URL(raw);
  const loopback = ['localhost', '127.0.0.1', '[::1]'].includes(u.hostname);
  if (u.username || u.password || u.search || u.hash || (u.pathname !== '/' && u.pathname !== '')) {
    throw new Error('Gateway must be an uncredentialed URL origin');
  }
  if (u.protocol !== 'https:' && !(u.protocol === 'http:' && loopback)) {
    throw new Error('Non-loopback Code Mode gateway must use HTTPS');
  }
  return u.origin;
}

async function main() {
  const sourceFile = process.argv[2];
  if (!sourceFile || process.argv.length !== 3) throw new Error('Usage: node codemode_host.mjs <operator-reviewed-script.js>');
  const info = await lstat(sourceFile);
  if (!info.isFile() || info.isSymbolicLink() || info.size < 1 || info.size > LIMIT) {
    throw new Error('Script must be a regular file of 1..65536 bytes');
  }
  const source = await readFile(sourceFile, 'utf8');
  const mission = requiredEnv('DOTTIE_CODEMODE_MISSION');
  if (!/^[a-f0-9]{32}$/.test(mission)) throw new Error('Invalid mission ID');
  const token = requiredEnv('DOTTIE_CODEMODE_AGENT_TOKEN');
  const gateway = authorizeEndpoint(requiredEnv('DOTTIE_CODEMODE_GATEWAY'));

  async function invoke(tool, args, signal) {
    if (typeof args !== 'object' || !args || Array.isArray(args)) throw new Error('Invalid tool arguments');
    const json = JSON.stringify({tool, args});
    if (json.length > 4096) throw new Error('Code Mode tool request too large');
    const response = await fetch(`${gateway}/v1/missions/${mission}/capability-call`, {
      method: 'POST', redirect: 'error', signal,
      headers: {'Authorization':`Bearer ${token}`, 'Content-Type':'application/json', 'Accept':'application/json'},
      body: json,
    });
    // Do not echo remote body, auth headers, or secrets on failure.
    if (!response.ok) throw new Error(`Dottie host rejected capability (${response.status})`);
    const length = Number(response.headers.get('content-length') || '0');
    if (length > 131072) throw new Error('Dottie tool result exceeds bounded response');
    const reply = await response.text();
    if (reply.length > 131072) throw new Error('Dottie tool result exceeds bounded response');
    const decoded = JSON.parse(reply);
    if (!Number.isInteger(decoded.receipt_seq) || !Object.hasOwn(decoded, 'result')) {
      throw new Error('Missing signed receipt or result in Dottie tool response');
    }
    return decoded.result;
  }

  const tools = [
    {name:'memory_read',description:'Read only memory in the running mission context; no other scopes.',
     inputSchema:{type:'object',properties:{scope:{type:'string'},limit:{type:'integer',minimum:1,maximum:12}},required:['scope'],additionalProperties:false},
     execute:async (args,{signal})=>invoke('memory.read',args,signal)},
    {name:'own_identity',description:'Read this principal identity metadata, never other identities or model bindings.',
     inputSchema:{type:'object',properties:{},additionalProperties:false},
     execute:async (args,{signal})=>invoke('identity.read',args,signal)},
    {name:'own_mission',description:'Read the authorized running mission and its scopes.',
     inputSchema:{type:'object',properties:{},additionalProperties:false},
     execute:async (args,{signal})=>invoke('mission.read',args,signal)}
  ];
  const sandbox = new CodemodeSandbox({timeoutMs:TIMEOUT_MS,memoryLimitBytes:16*1024*1024,tools});
  try {
    const result = await sandbox.execute(source);
    // Nested tool outputs may contain private authorized data. stdout is for
    // the trusted local operator only, never for an untrusted central log.
    const summary = {ok:result.ok, output:result.output, value:result.ok?result.value:null,
      error:result.ok?null:{kind:result.error?.kind || 'sandbox'},
      calls:Array.isArray(result.calls)?result.calls.map(c=>({name:c.name,status:c.status})):[]};
    process.stdout.write(JSON.stringify(summary)+'\n');
    if (!result.ok) process.exitCode = 2;
  } finally {
    await sandbox.close();
  }
}

main().catch(e=>{
  // Never include e.stack: a transport error can contain an internal URL.
  process.stderr.write(`Code Mode host refused execution: ${e instanceof Error ? e.message : 'unknown error'}\n`);
  process.exitCode=2;
});
