#!/usr/bin/env python3
"""Validate a detached, independently keyed release attestation.

A signature is only independent if the expected public-key fingerprint arrives
through a separately authenticated channel, never out of the ZIP under review.
This command verifies what a signer claimed; it does not assert field acceptance.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import re
from pathlib import Path


class WitnessError(ValueError):
    """Untrusted, unsigned, altered or unverifiable witness statement."""


def file_sha256(path:Path)->str:
    h=hashlib.sha256()
    with path.open('rb') as data:
        for chunk in iter(lambda:data.read(1024*1024),b''):
            h.update(chunk)
    return h.hexdigest()


def verify_witness(archive:Path,statement:Path,signature:Path,
                   trusted_public_key:Path,trusted_key_sha256:str)->dict:
    if not isinstance(trusted_key_sha256,str) or not re.fullmatch('[0-9a-f]{64}',trusted_key_sha256):
        raise WitnessError('a separately verified trusted public-key fingerprint is mandatory')
    try:
        key_bytes=Path(trusted_public_key).read_bytes()
    except OSError as exc:
        raise WitnessError('trusted public key unavailable') from exc
    if not key_bytes or hashlib.sha256(key_bytes).hexdigest()!=trusted_key_sha256:
        raise WitnessError('trusted public-key fingerprint mismatch; signer substitution denied')
    try:
        from cryptography.exceptions import InvalidSignature
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
    except ImportError as exc:
        raise WitnessError('cryptography optional dependency unavailable: install the [witness] extra') from exc
    try:
        pub=serialization.load_pem_public_key(key_bytes)
    except (ValueError,TypeError) as exc:
        raise WitnessError('invalid trusted Ed25519 public key') from exc
    if not isinstance(pub,Ed25519PublicKey):
        raise WitnessError('only Ed25519 external witnesses are supported')
    try:
        content=Path(statement).read_bytes()
        signature_bytes=Path(signature).read_bytes()
    except OSError as exc:
        raise WitnessError('witness statement or detached signature unavailable') from exc
    if not signature_bytes or len(signature_bytes)!=64:
        raise WitnessError('invalid or unsigned Ed25519 signature')
    if not content or len(content)>32*1024:
        raise WitnessError('invalid witness statement length')
    try:
        pub.verify(signature_bytes,content)
    except InvalidSignature as exc:
        raise WitnessError('external witness signature verification failed') from exc
    try:
        obj=json.loads(content)
    except (ValueError,UnicodeDecodeError) as exc:
        raise WitnessError('signed witness statement is not JSON') from exc
    if not isinstance(obj,dict) or obj.get('schema')!='gmri.external-witness.v1':
        raise WitnessError('unsupported signed witness schema')
    for name in ('reviewer_id','release_version','reviewed_at_utc','scope'):
        if not isinstance(obj.get(name),str) or not obj[name].strip() or len(obj[name])>1000:
            raise WitnessError('missing signed witness metadata '+name)
    recorded=obj.get('archive_sha256')
    if not isinstance(recorded,str) or not re.fullmatch('[0-9a-f]{64}',recorded):
        raise WitnessError('signed archive SHA-256 missing or malformed')
    try:
        actual=file_sha256(Path(archive))
    except OSError as exc:
        raise WitnessError('witnessed archive unavailable') from exc
    if actual!=recorded:
        raise WitnessError('archive SHA-256 differs from the signed witness statement')
    return {'valid':True,'schema':obj['schema'],'release_version':obj['release_version'],
            'reviewer_id':obj['reviewer_id'],'signed_scope':obj['scope'],
            'archive_sha256':actual,'trusted_key_sha256':trusted_key_sha256,
            'field_acceptance_not_established':True}


def main(argv=None):
    parser=argparse.ArgumentParser(description='Verify independent Ed25519 witness, not production acceptance')
    parser.add_argument('--archive',type=Path,required=True)
    parser.add_argument('--statement',type=Path,required=True)
    parser.add_argument('--signature',type=Path,required=True)
    parser.add_argument('--trusted-public-key',type=Path,required=True)
    parser.add_argument('--trusted-key-sha256',required=True,
                        help='Expected SHA256 of public PEM from independent secure channel')
    args=parser.parse_args(argv)
    try:
        result=verify_witness(args.archive,args.statement,args.signature,
                              args.trusted_public_key,args.trusted_key_sha256)
    except WitnessError as exc:
        print('FAIL: '+str(exc))
        return 2
    print(json.dumps(result,sort_keys=True,indent=2))
    return 0

if __name__=='__main__':raise SystemExit(main())
