/**
 * Dottie -> actual Pi Durable SDK HTTP protocol boundary (one identity per owner).
 * This module has no provider dependency; production pi_owner_runtime.mjs
 * injects a real SQLite-backed Harness. Tests inject a clearly labelled fake.
 * Every service response is attributable to the persisted upstream submission.
 * No model-offered tools, no public network listener, no data on stdout.
 */
import { createServer } from 'node:http';
import { createHash, timingSafeEqual } from 'node:crypto';
import { mkdir, lstat, readFile, open } from 'node:fs/promises';
import { join } from 'node:path';

const MAX_BODY = 65_536;
const MAX_PENDING_WAITS=16;
const HEX32=/^[a-f0-9]{32}$/;
const SAFE_ID=/^[A-Za-z0-9_-]{1,128}$/;
const sha=(data)=>createHash('sha256').update(data).digest('hex');
const payloadOf=(record)=>JSON.stringify(record)+'\n';

function authorized(raw, token) {
  if (!raw?.startsWith('Bearer ')) return false;
  const candidate=Buffer.from(raw.slice(7),'utf8');
  const expected=Buffer.from(token,'utf8');
  return candidate.length===expected.length && timingSafeEqual(candidate,expected);
}
function send(res,status,value){
  const body=JSON.stringify(value);
  res.writeHead(status,{'Content-Type':'application/json; charset=utf-8',
    'Content-Length':Buffer.byteLength(body),'Cache-Control':'no-store',
    'X-Content-Type-Options':'nosniff'});
  res.end(body);
}
async function checkedDirectory(dir){
  await mkdir(dir,{recursive:true,mode:0o700});
  const stat=await lstat(dir);
  if (!stat.isDirectory()||stat.isSymbolicLink()||(stat.mode&0o077)!==0)
    throw new Error('Owner state directory must be a private real directory');
}
async function readRecord(file){
  try{
    const stat=await lstat(file);
    if(!stat.isFile()||stat.isSymbolicLink()||stat.size>2048||(stat.mode&0o077)!==0)
      throw new Error('Unsafe persisted request mapping');
    return JSON.parse(await readFile(file,'utf8'));
  }catch(e){
    if(e?.code==='ENOENT')return null;
    throw e;
  }
}
async function storeRecord(file,data){
  // Existing records are immutable. Never silently overwrite a different claim.
  const f=await open(file,'wx',0o600);
  try{await f.writeFile(payloadOf(data),'utf8'); await f.sync()}
  finally{await f.close()}
  const parent=await open(join(file,'..'),'r');
  try{await parent.sync()}finally{await parent.close()}
}
function safeSubmissionId(value){
  const s=typeof value==='number' && Number.isSafeInteger(value) && value>=0
    ? String(value):value;
  if(typeof s!=='string'||!SAFE_ID.test(s))throw new Error('Pi supplied invalid submission id');
  return s;
}
function contentOf(message){
  if(!message||message.role!=='assistant')throw new Error('Not a Pi assistant response');
  const parts=message.content;
  const text=typeof parts==='string'?parts:Array.isArray(parts)?parts
    .filter(p=>p?.type==='text'&&typeof p.text==='string').map(p=>p.text).join(''):'';
  if(!text.trim()||Buffer.byteLength(text,'utf8')>64_000)throw new Error('Pi answer text absent or too long');
  return text;
}
async function parseBody(req){
  let size=0;const chunks=[];
  for await(const c of req){
    size+=c.length;
    if(size>MAX_BODY){const e=new Error('payload limit');e.status=413;throw e}
    chunks.push(c);
  }
  try{return JSON.parse(Buffer.concat(chunks).toString('utf8'))}
  catch{const e=new Error('malformed request');e.status=400;throw e}
}

export async function createOwnerServer({root,harness,context,token,session,dataDirectory}){
  if(typeof token!=='string'||token.length<16||!SAFE_ID.test(session)||!dataDirectory)
    throw new Error('Pi owner requires a strong token, fixed session and local data directory');
  const base=join(dataDirectory,'requests');
  const byRequest=join(base,'by_request');
  await checkedDirectory(dataDirectory);
  await checkedDirectory(base);
  await checkedDirectory(byRequest);
  const waiterMap=new Map();
  const agentPath=`/v1/sessions/${session}/agents/main`;
  const lookupPrefix=`/v1/sessions/${session}/submissions/`;
  async function noTools(){
    const a=await root.agent(context);
    if(!a||!Array.isArray(a.tools)||a.tools.length!==0||
       !Array.isArray(a.callable)||a.callable.length!==0)
      throw new Error('Provider retains executable/callable tools');
  }
  await noTools(); // Startup gate, then check again before every submission.
  const server=createServer(async (req,res)=>{
    if(!authorized(req.headers.authorization,token))return send(res,401,{error:'unauthorized'});
    if(req.headers['content-length'] && Number(req.headers['content-length'])>MAX_BODY)
      return send(res,413,{error:'request too large'});
    let path, url;
    try{url=new URL(req.url,'http://127.0.0.1');path=url.pathname}
    catch{return send(res,400,{error:'bad URL'})}
    try{
      if(path===agentPath && req.method==='GET'){
        await noTools();
        return send(res,200,{config:{readOnly:true},tools:[]});
      }
      if(path===`${agentPath}/messages` && req.method==='POST'){
        await noTools();
        const body=await parseBody(req);
        if(!body||typeof body!=='object'||Array.isArray(body)||
           Object.keys(body).some(k=>!['content','requestId','whenBusy','waitMs'].includes(k))||
           typeof body.content!=='string'||!body.content.trim()||
           Buffer.byteLength(body.content,'utf8')>60_000||
           !HEX32.test(body.requestId)||body.whenBusy!=='reject'||
           (body.waitMs!==undefined&&(!Number.isInteger(body.waitMs)||body.waitMs<0||body.waitMs>120_000)))
          return send(res,400,{error:'invalid scoped submission'});
        const id=body.requestId, contentHash=sha(body.content);
        const pathForRequest=join(byRequest,`${id}.json`);
        const previous=await readRecord(pathForRequest);
        if(previous){
          if(previous.requestId!==id||previous.contentSha256!==contentHash||
             !SAFE_ID.test(previous.submissionId))return send(res,409,{error:'request id collision'});
          const corroboration=await readRecord(join(base,`${previous.submissionId}.json`));
          if(JSON.stringify(corroboration)!==JSON.stringify(previous))
            return send(res,503,{error:'submission mapping integrity unavailable'});
          return send(res,202,{submissionId:previous.submissionId});
        }
        // Real Pi submit is idempotent by requestId, and atomically persists its
        // own acceptance. Sidecar mapping is fsynced *before* the HTTP ACK.
        const accepted=await root.submit({type:'input',content:body.content,requestId:id,whenBusy:'reject'},context);
        const submissionId=safeSubmissionId(accepted?.id);
        const record={schema:'gmri.pi-owner.submission.v1',submissionId,requestId:id,contentSha256:contentHash};
        const bySubmissionPath=join(base,`${submissionId}.json`);
        const existing=await readRecord(bySubmissionPath);
        if(existing && JSON.stringify(existing)!==JSON.stringify(record))
          return send(res,503,{error:'Pi submission ID collision in owner journal'});
        if(!existing)await storeRecord(bySubmissionPath,record);
        try{await storeRecord(pathForRequest,record)}catch(e){
          if(e?.code!=='EEXIST')throw e;
          const now=await readRecord(pathForRequest);
          if(JSON.stringify(now)!==JSON.stringify(record))
            return send(res,409,{error:'request id collision'});
        }
        return send(res,202,{submissionId});
      }
      if(path.startsWith(lookupPrefix)&&req.method==='GET'){
        const submissionId=path.slice(lookupPrefix.length);
        if(!SAFE_ID.test(submissionId))return send(res,404,{error:'unknown submission'});
        const record=await readRecord(join(base,`${submissionId}.json`));
        if(!record||record.submissionId!==submissionId||!HEX32.test(record.requestId))
          return send(res,404,{error:'unknown submission'});
        const inverse=await readRecord(join(byRequest,`${record.requestId}.json`));
        if(JSON.stringify(inverse)!==JSON.stringify(record))
          return send(res,503,{error:'submission attribution unavailable'});
        const waitMsRaw=url.searchParams.get('waitMs');
        const waitMs=waitMsRaw===null?0:Number(waitMsRaw);
        if(!Number.isSafeInteger(waitMs)||waitMs<0||waitMs>15_000||
           [...url.searchParams.keys()].some(k=>k!=='waitMs'))
          return send(res,400,{error:'invalid wait bound'});
        let waiting=waiterMap.get(submissionId);
        if(!waiting){
          if(waiterMap.size>=MAX_PENDING_WAITS)return send(res,503,{error:'pending wait budget reached'});
          const sub=harness.submission(Number.isSafeInteger(Number(submissionId))?Number(submissionId):submissionId);
          if(!sub||typeof sub.wait!=='function')return send(res,503,{error:'Pi submission missing'});
          // An unfinished wait stays attached once. Subsequent GETs reuse it.
          waiting=Promise.resolve().then(()=>sub.wait(context)).then(
             value=>({ok:true,value}),error=>({ok:false,error}));
          waiterMap.set(submissionId,waiting);
          void waiting.then(()=>{if(waiterMap.get(submissionId)===waiting)waiterMap.delete(submissionId)});
        }
        let timer;
        const timeout=new Promise(resolve=>{timer=setTimeout(()=>resolve(null),waitMs)});
        const result=await Promise.race([waiting,timeout]);
        clearTimeout(timer);
        if(result===null)return send(res,200,{status:'pending',requestId:record.requestId});
        if(!result.ok)return send(res,200,{status:'unanswered',requestId:record.requestId});
        const state=result.value;
        if(state?.status!=='done'||state.type!=='input')
          return send(res,200,{status:'unanswered',requestId:record.requestId});
        const message=state.answer?.model?.[0];
        const text=contentOf(message);
        return send(res,200,{status:'done',requestId:record.requestId,
          answer:{submissionRef:submissionId,text}});
      }
      return send(res,404,{error:'unknown route'});
    }catch(e){
      // No stack, tokens, private memory, or raw model reply in error surface.
      if(e?.status)return send(res,e.status,{error:e.message});
      return send(res,503,{error:'Pi owner cannot verify the requested operation'});
    }
  });
  return {
    get origin(){const a=server.address();return a?`http://127.0.0.1:${a.port}`:null},
    async listen(port=0){await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(port,'127.0.0.1',resolve)});
      return this.origin},
    async close(){if(server.listening)await new Promise((resolve,reject)=>server.close(e=>e?reject(e):resolve()))},
  };
}
