/**
 * Opt-in, one-identity Pi Durable host. NEVER auto-launched by the release.
 * Uses the real @earendil-works/pi-durable Harness.open(SQLite), not a fake SDK.
 * The host exposes ONLY Dottie's authenticated submit/status contract.
 * Existence/compilation of this file is not a live model inference receipt.
 *
 * Based on upstream Pi v1.3.0 packages/durable/README.md quick start.
 */
import {lstat, readFile, mkdir} from 'node:fs/promises';
import {resolve, join} from 'node:path';
import process from 'node:process';
import {createOwnerServer} from './pi_owner_contract.mjs';

async function runtime(){
  const [major,minor]=process.versions.node.split('.').map(Number);
  if(major<22 || (major===22&&minor<19))throw new Error('PINNED_NODE_VERSION_REQUIRED');
  const identity=process.env.DOTTIE_PI_OWNER_ID;
  if(!/^(?:dottie-hill|aegis-(?:dugan|jones|morita|falsworth|dernier))$/.test(identity||''))
    throw new Error('EXPLICIT_SINGLE_IDENTITY_REQUIRED');
  const modelId=process.env.DOTTIE_PI_MODEL_ID;
  if(typeof modelId!=='string'||!modelId.trim()||modelId.length>180)
    throw new Error('EXPLICIT_PROVIDER_MODEL_REQUIRED');
  if(!process.env.OPENAI_API_KEY)throw new Error('LIVE_PROVIDER_CREDENTIAL_NOT_PROVISIONED');
  const tokenFile=process.env.DOTTIE_PI_OWNER_TOKEN_FILE;
  const data=process.env.DOTTIE_PI_OWNER_DATA;
  if(!tokenFile||!data)throw new Error('EXTERNAL_TOKEN_AND_PRIVATE_DATA_DIRECTORY_REQUIRED');
  const keyStat=await lstat(tokenFile);
  if(!keyStat.isFile()||keyStat.isSymbolicLink()||(keyStat.mode & 0o077)!==0||
      (process.getuid && keyStat.uid!==process.getuid()))
    throw new Error('OWNER_TOKEN_FILE_MUST_BE_PRIVATE_AND_OWNED');
  const token=(await readFile(tokenFile,'utf8')).trim();
  if(token.length<32||token.length>256)throw new Error('OWNER_TOKEN_TOO_WEAK');
  const dir=resolve(data);
  await mkdir(dir,{recursive:true,mode:0o700});
  const stat=await lstat(dir);
  if(!stat.isDirectory()||stat.isSymbolicLink()||(stat.mode&0o077)!==0||
     (process.getuid && stat.uid!==process.getuid()))
    throw new Error('OWNER_DATA_DIRECTORY_MUST_BE_PRIVATE_AND_OWNED');
  // Real upstream imports fail closed when the reviewed/pinned dependency
  // closure is missing. This release does NOT install dependencies for you.
