import {readFile} from 'node:fs/promises';
import {dirname, join, parse} from 'node:path';
import {fileURLToPath} from 'node:url';

export async function readInstalledPackageMetadata(packageName, expectedVersion) {
  if (typeof packageName !== 'string' || !/^@[a-z0-9-]+\/[a-z0-9-]+$/.test(packageName)) {
    throw new TypeError('Invalid reviewed package name');
  }
  if (typeof expectedVersion !== 'string' || !/^\d+\.\d+\.\d+$/.test(expectedVersion)) {
    throw new TypeError('Invalid expected package version');
  }
  // The official entry point is exported even when ./package.json is not.
  const moduleEntry = import.meta.resolve(packageName);
  if (!moduleEntry.startsWith('file:')) throw new Error('SDK resolves outside a local file tree');
  let current = dirname(fileURLToPath(moduleEntry));
  for (let depth=0; depth<20; depth++) {
    const manifestPath=join(current,'package.json');
    let content;
