      const parent=dirname(current);
      if (parent===current) break;
      current=parent;
      continue;
    }
    // Fail on the first enclosing package even if it identifies itself as
    // something else; never roam upward to an unrelated matching manifest.
    let meta;
    try {meta=JSON.parse(content)} catch {throw new Error('Malformed SDK package manifest')}
    if (meta?.name!==packageName) throw new Error(`SDK package name mismatch for ${packageName}`);
    if (meta.version!==expectedVersion) throw new Error(`SDK version mismatch for ${packageName}`);
    return {name:meta.name, version:meta.version};
  }
  throw new Error(`Cannot locate installed SDK manifest for ${packageName}`);
}
