/**
 * Validate provenance that the genuine Pi SDK reports on a completed model
 * turn. This is NOT a signature from a model provider or an independent witness.
 * An operator-approved exact model is a mandatory equality constraint.
 */
import {createHash} from 'node:crypto';
const safeName=/^[A-Za-z0-9_.:\/-]{1,180}$/;
const responseHandle=/^[A-Za-z0-9_.:-]{1,240}$/;
const sha256=s=>createHash('sha256').update(s,'utf8').digest('hex');
function nonNegativeInteger(n) {return Number.isSafeInteger(n)&&n>=0}
export function validatedModelTurn(message, expectedProvider, expectedModel) {
  if(typeof expectedProvider!=='string'||!safeName.test(expectedProvider)||
     typeof expectedModel!=='string'||!safeName.test(expectedModel))
    throw new Error('EXPECTED_MODEL_NOT_OPERATOR_SPECIFIED');
  if(!message||message.role!=='assistant'||
     message.provider!==expectedProvider||message.model!==expectedModel||
     (message.responseModel!==undefined&&message.responseModel!==expectedModel))
    throw new Error('PI_MODEL_IDENTITY_DIFFERS_FROM_OPERATOR_APPROVAL');
  if(message.stopReason!=='stop'||!Array.isArray(message.content)||
     message.content.some(block=>!block||!['text','thinking'].includes(block.type)))
    throw new Error('PI_MODEL_TURN_NOT_FINAL_OR_CONTAINS_TOOLS');
  const text=message.content.filter(x=>x.type==='text').map(x=>x.text).join('');
  if(!text.trim()||Buffer.byteLength(text,'utf8')>64000)
    throw new Error('PI_MODEL_TEXT_MISSING_OR_TOO_LONG');
  if(!Number.isSafeInteger(message.timestamp)||message.timestamp<0)
    throw new Error('PI_MODEL_TIMESTAMP_INVALID');
  const u=message.usage;
  if(!u||!nonNegativeInteger(u.input)||!nonNegativeInteger(u.output)||
     !nonNegativeInteger(u.totalTokens)||u.totalTokens<u.output)
    throw new Error('PI_MODEL_USAGE_INVALID');
  if(message.responseId!==undefined && (!responseHandle.test(message.responseId)))
    throw new Error('PI_MODEL_RESPONSE_IDENTIFIER_INVALID');
  return Object.freeze({
    schema:'gmri.pi-owner-model-turn.v1',
    provenance:'pi_sdk_reported_not_independent',
    independentlyWitnessed:false,
    provider:expectedProvider,model:expectedModel,
    ...(message.responseId===undefined?{}:{responseId:message.responseId}),
    stopReason:'stop',timestamp:message.timestamp,
    textSha256:sha256(text),
    usage:{input:u.input,output:u.output,totalTokens:u.totalTokens},
  });
}
