/**
 * Host-owned, six-identity OS UID binding for the Pi owner.
 * A claimed identity string is never proof of who owns a running process.
 * Production requires a trusted, root-owned manifest outside tenant stores.
 */
import {lstat, readFile} from 'node:fs/promises';
import {dirname, isAbsolute} from 'node:path';

export const CANONICAL_OWNERS = Object.freeze([
  'dottie-hill', 'aegis-dugan', 'aegis-jones', 'aegis-morita',
  'aegis-falsworth', 'aegis-dernier',
]);

function objectWithExactKeys(value, expected){
  return value!==null && typeof value==='object' && !Array.isArray(value) &&
    Object.keys(value).sort().join('\0')===expected.slice().sort().join('\0');
}

export function validateOwnerManifest(manifest, identity, uid, port){
  if(!objectWithExactKeys(manifest,['schema','principals']) ||
     manifest.schema!=='gmri.pi-os-tenancy.v1')
    throw new Error('INVALID_TENANCY_SCHEMA');
  const principals=manifest.principals;
  if(!objectWithExactKeys(principals,CANONICAL_OWNERS))
    throw new Error('TENANCY_EXACT_SIX_REQUIRED');
  const uids=new Set();
  const ports=new Set();
  for(const member of CANONICAL_OWNERS){
    const binding=principals[member];
    if(!objectWithExactKeys(binding,['uid','port']))
      throw new Error('INVALID_PRINCIPAL_BINDING');
    if(!Number.isSafeInteger(binding.uid) || binding.uid<1000 || binding.uid>0x7ffffffe)
      throw new Error('TENANCY_INVALID_UID');
    if(!Number.isSafeInteger(binding.port) || binding.port<1024 || binding.port>65535)
      throw new Error('TENANCY_INVALID_PORT');
    if(uids.has(binding.uid) || ports.has(binding.port))
      throw new Error('TENANCY_DUPLICATE_BINDING');
    uids.add(binding.uid);ports.add(binding.port);
  }
  if(!CANONICAL_OWNERS.includes(identity))throw new Error('UNKNOWN_TENANCY_IDENTITY');
  if(!Number.isSafeInteger(uid) || uid!==principals[identity].uid)
    throw new Error('TENANCY_UID_BINDING_MISMATCH');
  if(!Number.isSafeInteger(port) || port!==principals[identity].port)
    throw new Error('TENANCY_PORT_BINDING_MISMATCH');
  return {identity,uid,port};
}

function checkStat(stat,kind,expectedUid,privateOnly){
  if(stat.isSymbolicLink() || (kind==='file'&&!stat.isFile()) ||
     (kind==='directory'&&!stat.isDirectory()))throw new Error('UNSAFE_TENANCY_FILE_TYPE');
  if(stat.uid!==expectedUid)throw new Error('TENANCY_FILE_OWNER_MISMATCH');
  if((stat.mode & (privateOnly?0o077:0o022))!==0)
    throw new Error('TENANCY_FILE_PERMISSIONS_TOO_BROAD');
}

/** Return token only to the owner runtime, never to CLI stdout or receipts. */
export async function verifyOwnerTenancy({identity,port,manifestFile,tokenFile,dataDirectory}){
  if(typeof process.getuid!=='function')throw new Error('UNIX_PROCESS_REQUIRED');
  const uid=process.getuid();
  if(uid===0)throw new Error('ROOT_OWNER_PROCESS_FORBIDDEN');
  if(![manifestFile,tokenFile,dataDirectory].every(x=>typeof x==='string'&&isAbsolute(x)))
    throw new Error('ABSOLUTE_OS_TENANCY_PATHS_REQUIRED');
  const manifestStat=await lstat(manifestFile);
  const parentStat=await lstat(dirname(manifestFile));
  checkStat(manifestStat,'file',0,false);
  checkStat(parentStat,'directory',0,false);
  const manifest=JSON.parse(await readFile(manifestFile,'utf8'));
  const claim=validateOwnerManifest(manifest,identity,uid,port);
  const tokenStat=await lstat(tokenFile);
  const dataStat=await lstat(dataDirectory);
  checkStat(tokenStat,'file',uid,true);
  checkStat(dataStat,'directory',uid,true);
  const token=(await readFile(tokenFile,'utf8')).trim();
  if(token.length<32 || token.length>256 || !/^[A-Za-z0-9_-]+$/.test(token))
    throw new Error('OWNER_TOKEN_INVALID');
  return {...claim,token};
}
EOF
